#include<queue>
using namespace std;
​
​
 int m,n;
int BFS(vector<vector<bool>>& visited, vector<vector<int>>& grid, int x, int y) {
    visited[x][y] = 1;
    // 记录连通岛屿体积
    int count = grid[x][y];
    int directed[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    queue<pair<int, int>> q;
    q.push({x, y});
    while (!q.empty()) {
        pair<int, int> current = q.front();
        q.pop();
        for (int i = 0; i < 4; i++) {
            int newX = current.first + directed[i][0];
            int newY = current.second + directed[i][1];
            // 超过边界
            if (newX < 0 || newY < 0 || newX >= n || newY >= m) {
                continue;
            }
            // 访问过或者为水
            if (visited[newX][newY] || grid[newX][newY] == 0) {
                continue;
            }
            // 岛屿体积 
            count  += grid[newX][newY];
            visited[newX][newY] = true;
            q.push({newX, newY});
        }
    }
    return count;
}
​
int main() {

    cin >> m >> n;
    vector<vector<int>> grid(n, vector<int>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
        }
    }
    int res = 0;
​
    // 使用BFS最大值
    vector<vector<bool>> visited(n, vector<bool>(m, false));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (!visited[i][j] && grid[i][j] > 0) {
                int count = BFS(visited, grid, i, j);
                res = max(res, count);
            }
        }
    }
    cout << res;
    return 0;
}
