package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
var m, n int
var grid [][]int
var visited [][]bool
var dirs = [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
​
// BFS 搜索岛屿体积
func bfs(x, y int) int {
    queue := [][2]int{{x, y}}
    visited[x][y] = true
    count := grid[x][y]
​
    for len(queue) > 0 {
        curr := queue[0]
        queue = queue[1:]
        for _, d := range dirs {
            nx, ny := curr[0]+d[0], curr[1]+d[1]
            // 跳过 越界 访问过 水的情况
            if nx >= 0 && ny >= 0 && nx < n && ny < m && !visited[nx][ny] && grid[nx][ny] > 0 {
                visited[nx][ny] = true
                queue = append(queue, [2]int{nx, ny})
                count += grid[nx][ny]
            }
        }
    }
    return count
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    parts := strings.Fields(scanner.Text())
    m, _ = strconv.Atoi(parts[0])
    n, _ = strconv.Atoi(parts[1])
​
    grid = make([][]int, n)
    visited = make([][]bool, n)
    for i := 0; i < n; i++ {
        scanner.Scan()
        rowStr := strings.Fields(scanner.Text())
        row := make([]int, m)
        for j := 0; j < m; j++ {
            row[j], _ = strconv.Atoi(rowStr[j])
        }
        grid[i] = row
        visited[i] = make([]bool, m)
    }
​
    res := 0
    for i := 0; i < n; i++ {
        for j := 0; j < m; j++ {
            // 统计岛屿体积
            if !visited[i][j] && grid[i][j] > 0 {
                if count := bfs(i, j); count > res {
                    res = count
                }
            }
        }
    }
    fmt.Println(res)
}
